(()=>{'use strict';const P=window.DEMO_PAGE,C=window.DEMO_CONTEXT,A=window.CELL_UI_ASSETS,profile=A?.profiles[P?.id];if(!profile||!C)return;const style=document.createElement('style');style.textContent='.demo-observed-cell{position:relative;width:100%;min-width:0}.demo-observed-cell .editable-cell-content{padding:6px 8px}.demo-observed-cell .mask[aria-disabled=true]{cursor:not-allowed}.demo-observed-link{border:0;background:transparent;padding:0;color:#1686ae;opacity:1;font:inherit;max-width:100%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;cursor:not-allowed}.demo-observed-link:hover{text-decoration:underline}';document.head.append(style);const numberStyle=document.createElement('style');numberStyle.textContent='.demo-wo-number-value{padding:6px 8px;height:100%;box-sizing:border-box}.demo-wo-number:hover .demo-wo-number-value{padding-right:8px}.demo-wo-number-edit{width:24px;height:24px;right:4px;background:rgba(255,255,255,.5);color:#333;display:flex;align-items:center;justify-content:center;cursor:not-allowed}';document.head.append(numberStyle); // NATIVE_NUMBER_HOVER_V9

const bases=[...document.querySelectorAll('.kodo-art-table')].filter(t=>!t.closest('[role=dialog]'));function wire(){if(P.id==='BL-04-01')document.querySelectorAll('.demo-wo-number').forEach(box=>{if(box.dataset.nativeNumberHover)return;box.dataset.nativeNumberHover='1';box.classList.add('basic-cell');box.dataset.mode='edit';const cell=box.closest('.kodo-art-table-cell');cell.style.setProperty('padding','0','important');cell.style.transform='none';const edit=box.querySelector('.demo-wo-number-edit');edit.classList.add('mask');edit.innerHTML=A.pencil;});for(const table of bases){const head=table.querySelector('.kodo-art-table-thead .kodo-art-table-row'),headers=head?[...head.children].flatMap(h=>h.hasAttribute('colspan')?[...h.querySelectorAll('.kodo-art-table-header-cell-child')]:[h]):[];table.querySelectorAll('.kodo-art-table-tbody .kodo-art-table-row:not(.kodo-art-table-measure-row)').forEach(row=>{if(row.dataset.demoRecord||row.children.length!==headers.length)return;[...row.children].forEach((cell,i)=>cell.dataset.demoColumn=headers[i].textContent.trim());});}bases.flatMap(t=>[...t.querySelectorAll('.kodo-art-table-tbody [data-demo-column]')]).forEach(cell=>{const field=cell.dataset.demoColumn,config=profile[field];if(!config)return;if(config.tooltip&&!(P.id==='BL-04-01'&&field==='工单编号'))cell.dataset.observedFullValue='1';if(config.pencil&&P.id!=='BL-04-01'&&!cell.querySelector('.demo-observed-cell')){const previous=cell.querySelector('.editable-cell-content'),nodes=[...(previous||cell).childNodes],content=document.createElement('div'),box=document.createElement('div'),body=document.createElement('div'),mask=document.createElement('div');cell.replaceChildren();content.className='editable-cell-content';content.append(...nodes);box.className='editable-cell-content-box';box.style.height='100%';box.append(content);body.className='basic-cell demo-observed-cell';body.dataset.mode='edit';mask.className='mask';mask.dataset.cellEditorPending=field;mask.setAttribute('role','button');mask.setAttribute('aria-label','编辑'+field+'（恢复路径待核实）');mask.setAttribute('aria-disabled','true');mask.title='源站行内编辑恢复路径尚未核实';mask.innerHTML=A.pencil;body.append(mask,box);cell.style.setProperty('padding','0','important');cell.style.transform='none';cell.append(body);}if(config.link&&!(P.id==='BL-04-01'&&field==='工单编号')&&!cell.querySelector('.demo-observed-link')){const content=cell.querySelector('.editable-cell-content')||cell,text=content.textContent,link=document.createElement('button');link.type='button';link.className='demo-observed-link';link.disabled=true;link.textContent=text;link.setAttribute('aria-label','查看'+field+'（恢复路径待核实）');link.title='源站链接目标及恢复路径尚未核实';content.replaceChildren(link);}});}
wire();const tbody=document.querySelector('.kodo-art-table-tbody');if(tbody)new MutationObserver(wire).observe(tbody,{childList:true,subtree:true});window.addEventListener('click',e=>{if(e.target.closest('[data-cell-editor-pending]')){e.preventDefault();e.stopImmediatePropagation();C.toast('源站行内编辑恢复路径尚未核实，此项暂不可编辑');}},true);
let tip,timer,closeTimer,anchor;function close(){clearTimeout(timer);clearTimeout(closeTimer);timer=null;tip?.remove();tip=null;anchor=null;}function show(cell){close();if(!cell.isConnected)return;anchor=cell;const t=document.createElement('template');t.innerHTML=A.tooltip.html;tip=t.content.firstElementChild;tip.style.cssText='position:fixed;inset:auto;z-index:1030;pointer-events:auto;box-sizing:border-box;--antd-arrow-background-color:rgba(0,0,0,.7)';const text=tip.querySelector('.the-popover-content');text.textContent=cell.querySelector('.editable-cell-content')?.textContent||cell.textContent;for(const[k,v]of Object.entries(A.tooltip.font))text.style.setProperty(k,v);document.body.append(tip);const r=cell.getBoundingClientRect(),w=tip.getBoundingClientRect().width,h=tip.getBoundingClientRect().height;tip.style.left=Math.max(4,Math.min(innerWidth-w-4,Math.floor(r.x+(r.width-1)/2-w/2)))+'px';tip.style.top=Math.floor(r.top-h-5)+'px';tip.querySelector('.kodo-new-popover-arrow').style.cssText='position:absolute;bottom:0;left:50%';}
document.addEventListener('pointerover',e=>{const cell=e.target.closest('[data-observed-full-value]');if(cell){clearTimeout(closeTimer);if(anchor===cell||timer)return;timer=setTimeout(()=>show(cell),100);}else if(tip?.contains(e.target))clearTimeout(closeTimer);else{clearTimeout(timer);timer=null;clearTimeout(closeTimer);closeTimer=setTimeout(close,100);}},true);window.addEventListener('pointerdown',e=>{if(!tip?.contains(e.target))close();},true);window.addEventListener('scroll',e=>{if(!(e.target instanceof Node)||!tip?.contains(e.target))close();},true);window.addEventListener('keydown',e=>{if(e.key==='Escape')close();},true);document.documentElement.dataset.observedCellsReady='1';})();

